#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM${e}[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
  # Never trace credentials, including when the caller starts Bash with -x/-v.
  set +x +v
  TOTAL_STAGES=5
  local hsl_mode="${1:-}" hsl_python hsl_helper hsl_script hsl_phase hsl_build hsl_developer hsl_certificate hsl_source
  local hsl_directory="$HOME/HomePodSensorLink-Export"
  if [[ "$hsl_mode" == --help ]]; then
    printf '%s\n' 'Usage: bash scripts/macos_homekit_wizard.sh [--restore | --help]' \
      'Run in Terminal on an Apple silicon Mac; rerun the same command after each reboot.' \
      'The script builds the bundled Swift helper without downloading packages; signing and export require confirmation.' \
      'Security changes and restarts are manual. --restore prints the saved restoration steps.' \
      'Private files stay in ~/HomePodSensorLink-Export. Never share this folder.'
    return
  fi
  if [[ $# -gt 1 || ( -n "$hsl_mode" && "$hsl_mode" != --restore ) ]]; then
    printf '%s\n' 'Unknown option. Use --help.' >&2
    return 1
  fi
  if [[ "$(uname -s)" != Darwin || "$(uname -m)" != arm64 || "$EUID" == 0 ]]; then
    printf '%s\n' 'Run as your normal user in native Terminal on an Apple silicon Mac, without sudo or Rosetta.' >&2
    return 1
  fi
  if [[ ! -t 0 || ! -t 1 ]]; then
    printf '%s\n' 'Run interactively in Terminal; do not pipe, log or record this wizard.' >&2
    return 1
  fi
  umask 077
  hsl_python=$(command -v python3) || { warn 'Install Python 3.9+ before continuing.'; return 1; }
  "$hsl_python" -c 'import sys; raise SystemExit(sys.version_info < (3, 9))' || return 1
  hsl_script="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)/$(basename "${BASH_SOURCE[0]}")"
  hsl_helper="$(dirname "$hsl_script")/macos_homekit_export.py"
  hsl_phase=$("$hsl_python" "$hsl_helper" status "$hsl_directory") || {
    printf '%s\n' "$hsl_phase" >&2
    return 1
  }

  # EXIT also covers errors and cancelled prompts. This prints recovery commands;
  # it never invokes sudo, writes NVRAM, changes SIP/AMFI or reboots the Mac.
  hsl_on_exit() {
    local hsl_code=$? hsl_saved_phase
    trap - EXIT INT TERM
    hsl_saved_phase=$("$hsl_python" "$hsl_helper" status "$hsl_directory" 2>/dev/null) || hsl_saved_phase=unknown
    if [[ "$hsl_saved_phase" == extract || "$hsl_saved_phase" == restore ]]; then
      printf '\n'
      warn 'If you changed security settings, restore them even when extraction failed or was cancelled.'
      "$hsl_python" "$hsl_helper" restore "$hsl_directory" || true
    fi
    exit "$hsl_code"
  }
  trap hsl_on_exit EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  if [[ "$hsl_mode" == --restore ]]; then
    "$hsl_python" "$hsl_helper" restore "$hsl_directory"
    exit 0
  fi

  banner 'HomePod Sensor Link: macOS key export'
  stage 'Prerequisites and build'
  if [[ "$hsl_phase" == new ]]; then
    "$hsl_python" "$hsl_helper" initial "$hsl_directory"
    say 'Use the Apple Account that manages your HomePods. Confirm they are visible in Home.'
    say 'This experimental route temporarily requires SIP and AMFI to be disabled by you.'
    say 'Use the manual wiki guide for managed Macs or custom security policies.'
    open_url 'https://github.com/barneyonline/ha-homepod-sensor-link/wiki/Credential-Extraction'
    step 'Install Xcode or its Command Line Tools. A valid Apple Development signing certificate is also required.'
    step 'To create a certificate in Xcode: Settings → Accounts → Manage Certificates → + → Apple Development.'
    confirm 'Ready to compile the bundled helper locally, with normal protections enabled?' || exit 1
    hsl_developer="${DEVELOPER_DIR:-$(/usr/bin/xcode-select -p)}"
    if [[ ! -d "$hsl_developer" ]]; then
      warn 'Select the installed Xcode or Command Line Tools, then rerun.'
      exit 1
    fi
    if [[ -e "$hsl_directory/tool-source.txt" || -L "$hsl_directory/tool-source.txt" ]]; then
      warn 'A tool exists without a saved snapshot. Keep protections enabled and use the manual guide.'
      exit 1
    fi
    if [[ -e "$hsl_directory/homekit-keys.txt" || -L "$hsl_directory/homekit-keys.txt" ]]; then
      warn 'An existing key dump would conflict with this run. Keep protections enabled and use the manual guide.'
      exit 1
    fi
    hsl_build=$(mktemp -d "$hsl_directory/build.XXXXXX")
    say 'Building from this checkout with Apple frameworks. Build output stays in the private build folder.'
    if ! DEVELOPER_DIR="$hsl_developer" sh "$(dirname "$hsl_script")/build_macos_homekit.sh" \
      "$hsl_build/HomeKitExport" > "$hsl_build/build.txt" 2>&1; then
      warn 'Build failed. Keep protections enabled. Check the private build.txt for compiler or SDK errors.'
      exit 1
    fi
    (set -o noclobber; printf '%s\n' "$hsl_build/HomeKitExport" > "$hsl_directory/tool-source.txt")
  else
    say 'The prepared tool and original-settings snapshot are retained from your earlier run.'
  fi

  stage 'Save original security settings'
  if [[ "$hsl_phase" == new ]]; then
    "$hsl_python" "$hsl_helper" snapshot "$hsl_directory"
    say 'Original boot arguments saved privately, including whether the variable was absent.'
  else
    say 'Using the original snapshot. It will not be replaced during later runs.'
  fi

  stage 'Manual security changes and reboots'
  if [[ "$hsl_phase" == new ]]; then
    step 'Shut down. Hold the power button for Options → Continue and authenticate.'
    step 'In Recovery, open Utilities → Terminal and run these two commands:'
    say 'csrutil disable'
    say 'reboot'
    step 'Back in normal macOS Terminal, run the following command, then restart again:'
    "$hsl_python" "$hsl_helper" enable "$hsl_directory"
    say 'After that second restart, rerun this exact wizard command:'
    printf '  bash %q\n' "$hsl_script"
    exit 0
  fi
  if [[ "$hsl_phase" == extract ]]; then
    "$hsl_python" "$hsl_helper" check-extract "$hsl_directory"
    say 'SIP is disabled and the temporary AMFI argument is present in the running kernel.'
  else
    say 'Extraction was attempted earlier. Continue directly to restoring protections.'
  fi

  stage 'Export the HomeKit group privately'
  if [[ "$hsl_phase" == extract ]]; then
    hsl_source=$("$hsl_python" "$hsl_helper" source "$hsl_directory") || {
      printf '%s\n' "$hsl_source" >&2
      exit 1
    }
    step 'In Keychain Access, copy the complete name of your valid Apple Development certificate.'
    ask hsl_certificate 'Certificate name (not a key):'
    [[ -n "$hsl_certificate" ]] || exit 1
    confirm 'Sign the bundled helper with this certificate, then export com.apple.hap.pairing privately?' || exit 1
    # Record restoration as the next task before invoking the third-party tool.
    "$hsl_python" "$hsl_helper" extracted "$hsl_directory"
    if ! (
      set -o noclobber
      /usr/bin/codesign --force --sign "$hsl_certificate" --entitlements "$hsl_source/HomeKitExport.entitlements" \
        "$hsl_source/homekit-export" > "$hsl_source/signing.txt" 2>&1 &&
      /usr/bin/codesign --verify --strict "$hsl_source/homekit-export" >> "$hsl_source/signing.txt" 2>&1 &&
      "$hsl_source/homekit-export" --export-hap > "$hsl_directory/homekit-keys.txt" 2>&1
    ); then
      warn 'Extraction did not complete. Restore protections now, then inspect the private dump locally.'
      exit 1
    fi
    say 'The process exited. This alone does not confirm that usable keys were found.'
    say 'Restore protections using the instructions below, then rerun this wizard.'
    exit 0
  fi

  stage 'Verify restoration and prepare the selected import'
  "$hsl_python" "$hsl_helper" check-restored "$hsl_directory"
  say 'SIP and the original boot arguments are restored; the running kernel has no AMFI override.'
  [[ -s "$hsl_directory/homekit-keys.txt" && ! -L "$hsl_directory/homekit-keys.txt" ]] || {
    warn 'No private dump is available. Protections are restored; use the manual extraction guide.'
    exit 1
  }
  say 'Open homekit-keys.txt locally. Find the HomeKit Pairing Identity and selected Paired HomeKit Accessory records.'
  say 'Stop if keys are missing or shown only as binary placeholders. Do not guess which identity is authorised.'
  confirm 'Ready to enter only the selected credentials into a private JSON bundle?' || exit 1
  "$hsl_python" "$hsl_helper" export "$hsl_directory"
  say 'In HA: Settings → Devices & services → Add integration → HomePod Sensor Link.'
  say 'Choose your devices, then Paste a CSV or JSON export. Paste the selected JSON file contents.'
  say 'Use a local administrator session over HTTPS. HA verifies identities, key pairs, pins and permissions.'
  say 'After successful setup, remove unnecessary dump/export copies and clear copied keys from the clipboard.'
  say 'Keep this folder private. It contains controller credentials; never attach it to an issue.'
  (set +u; finish)
  exit 0
}

run_wizard "$@"; exit
